<?php namespace App\Filament\Resources; use App\Filament\Resources\AdminAuditLogResource\Pages; use App\Models\AdminAuditLog; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder; class AdminAuditLogResource extends AdminResource {protected static ?string $model=AdminAuditLog::class;protected static string|null|\BackedEnum $navigationIcon='heroicon-o-clipboard-document-list';protected static string|\UnitEnum|null $navigationGroup='Système';protected static ?int $navigationSort=2;protected static ?string $navigationLabel="Journal d'audit";public static function canCreate():bool{return false;}public static function canEdit(\Illuminate\Database\Eloquent\Model $r):bool{return false;}public static function canDelete(\Illuminate\Database\Eloquent\Model $r):bool{return false;}public static function getEloquentQuery():Builder{return parent::getEloquentQuery()->with('admin');}public static function form(Schema $s):Schema{return $s->components([]);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('created_at')->label('Date')->dateTime('d/m/Y H:i:s')->sortable(),TextColumn::make('admin.name')->label('Administrateur')->placeholder('Compte supprimé'),TextColumn::make('action')->label('Action')->badge()->searchable(),TextColumn::make('subject_type')->label('Objet')->formatStateUsing(fn($state)=>class_basename($state)),TextColumn::make('subject_id')->label('ID'),TextColumn::make('changes')->label('Détails')->formatStateUsing(fn($state)=>$state?json_encode($state,JSON_UNESCAPED_UNICODE):'—')->limit(80)])->filters([SelectFilter::make('action')->options(fn()=>AdminAuditLog::query()->distinct()->pluck('action','action')->all())])->defaultSort('created_at','desc');}public static function getPages():array{return ['index'=>Pages\ListAdminAuditLogs::route('/')];}}
